window.LESSONS.push(...[{"id": "fyzika-6-01", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Co je to fyzika", "time": "10–20 min", "tag": "6. ročník · téma 1", "explain": "Fyzika je věda, která zkoumá zákonitosti přírodních jevů. Popisuje vlastnosti a projevy hmoty, přírodních sil,světla, neviditelného záření, tepla, zvuku atd.", "paragraphs": ["Fyzika je věda, která zkoumá zákonitosti přírodních jevů. Popisuje vlastnosti a projevy hmoty, přírodních sil,světla, neviditelného záření, tepla, zvuku atd.", "Základy dnešní fyziky položil Galileo Galilei", "Ve fyzice budeme používat metody pozorování, experimentu. Mnohé zákonitosti jsou zapsány pomocí matematických vztahů.", "Fyzika se dělí na odvětví", "-mechanika", "-molekulová fyzika", "-atomová fyzika", "-elektromagnetismus", "-akustika", "-optika", "-astronomie", "atp.", "Fyzika je součástí školních osnov jako povinný předmět, ale to by neměl být jediný důvod k jejímu studiu. Nabízí praktické využití v denním životě, pomáhá nám porozumět našemu světu."], "diagram": "/schemata/fyzika-6-01.svg", "caption": "Postup fyzikálního zkoumání: pozorování, měření a porovnání výsledků.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-02", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Těleso a látka", "time": "10–20 min", "tag": "6. ročník · téma 2", "explain": "Těleso: osoba, zvíře nebo věc, která má určitý tvar, rozměry a polohu. Tělesem je například sklenice, voda ve sklenici nebo vzduch v místnosti.", "paragraphs": ["Těleso: osoba, zvíře nebo věc, která má určitý tvar, rozměry a polohu. Tělesem je například sklenice, voda ve sklenici nebo vzduch v místnosti.", "Tělesa jsou tvořena látkami. Látka je materiál, ze kterého je těleso vytvořeno, například voda, sklo, železo nebo dřevo.", "Látka: tvoří tělesa"], "diagram": "/schemata/fyzika-6-02.svg", "caption": "Postup fyzikálního zkoumání: pozorování, měření a porovnání výsledků.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-03", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Skupenství látek", "time": "10–20 min", "tag": "6. ročník · téma 3", "explain": "Látky se mohou nacházet v různých skupenstvích pevné, kapalné a plynné.", "paragraphs": ["Látky se mohou nacházet v různých skupenstvích pevné, kapalné a plynné.", "Názvy skupenství vody", "Pevné - led", "Kapalné - voda", "Plynné - vodní pára", "Vlastnosti skupenství", "plynné skupenství -snadno mění svůj tvar - je stlačitelné", "kapalné skupenství -snadno mění svůj tvar, není stlačitelné", "pevné skupenství -není stlačitelné a nemění snadno svůj tvar", "Kapaliny a plyny označujeme souhrnným jménem tekutiny-mají společnou vlastnost - jdou přelévat.", "Online simulace skupenství:", "https://phet.colorado.edu/cs/simulations/gases-intro", "https://phet.colorado.edu/sims/html/states-of-matter-basics/latest/states-of-matter-basics_all.html?locale=cs"], "diagram": "/schemata/fyzika-6-03.svg", "caption": "Částicový model skupenství. Body představují částice, nikoli jejich skutečný tvar či velikost.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-04", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Atomy a molekuly", "time": "10–20 min", "tag": "6. ročník · téma 4", "explain": "Atom", "paragraphs": ["Atom", "slovo atom pochází z řeckého slova atomos - nedělitelný.", "Pojmem atom označujeme základní částice, které tvoří všechny látky.", "Dnes víme, že se atom může dělit na jednodušší části.", "Molekula", "Spojení dvou a více atomu - např. molekula vody.", "Atom + atom + atom (2xatom vodíku (H) a 1x atom kyslíku(O))", "Prvek", "Látka, která je tvořena ze stejných atomů - např. zlata.", "Sloučenina", "Látka tvořena z různých atomů.", "Vlastnosti atomů a molekul", "Společnou vlastností částic je to, že se neustále pohybují - základní vlastností atomů a molekul je to, že jsou v neustálém neuspořádaném pohybu.", "Příklady pohybů: Brownův pohyb nebo difúze."], "diagram": "/schemata/fyzika-6-04.svg", "caption": "Částicový model skupenství. Body představují částice, nikoli jejich skutečný tvar či velikost.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-05", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Veličiny a jejich měření", "time": "10–20 min", "tag": "6. ročník · téma 5", "explain": "Fyzikální veličiny slouží k popisu těles, vzdáleností, fyzikálních jevů a dalších vlastností.", "paragraphs": ["Fyzikální veličiny slouží k popisu těles, vzdáleností, fyzikálních jevů a dalších vlastností.", "Každá fyzikální veličina má své písmeno, které jí nahrazuje.", "U většiny veličin je také jednotka, která upřesňuje její hodnotu.", "Písmenka jsou mezinárodně uznávaná a jsou zapsána v tabulkách.", "Vychází z jednotného systému SI.", "Příklad české věty: hmotnost je osmdesát kilogramů", "Fyzik napíše: m = 80 kg", "Vždy musím umět", "zapsat veličinu písmenem dle systému SI", "vysvětlit co veličina popisuje", "její základní jednotku a převody mezi dalšími odvozenými jednotkami", "změřit veličinu na zadaném měřidle", "Příklad (mohu si pomoci angličtnou)", "Délka", "l", "Hmotnost", "m", "Objem", "V", "Čas", "t", "Teplota", "t", "Je dobré znát obecné předpony pro jednotky, které se často používají (rozšiřující učivo)", "mikro označení μ", "mili - označeni m", "deci - označeni d", "centi - označeni c", "kilo - označení k", "mega - označení M", "giga - označení G", "Např. milimetr, mililitr nebo kilometr, kilogram atp."], "diagram": "/schemata/fyzika-6-05.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-06", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Délka", "time": "10–20 min", "tag": "6. ročník · téma 6", "explain": "Charakteristika: délka je fyzikální veličina, která popisuje rozměry těles a vzdálenosti mezi tělesy.", "paragraphs": ["Charakteristika: délka je fyzikální veličina, která popisuje rozměry těles a vzdálenosti mezi tělesy.", "Označení veličiny: l (v některých knihách ale i d) Jednotka: metr (m).", "Pochází z Francie a byla vypočtena jako jedna desetimiliontina vzdálenosti severního polů k rovníku.", "Další jednotky: kilometr (km), decimetr(dm), centimetr (cm), mikrometr (rozšiřující učivo μm).", "Slovní spojení: délka je osmdesát tisíc centimetrů, zapíši: l = 80 000 cm", "Mezi číslem a jednotkou dělám mezeru, za tisícem nebo tisícinou také udělám mezeru. Pomůcka:"], "diagram": "/schemata/fyzika-6-06.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-07", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Měření délky", "time": "10–20 min", "tag": "6. ročník · téma 7", "explain": "Myšlenka: Při měření délky zjišťujeme, kolikrát je jednotka délky obsažena v měřeném úseku.", "paragraphs": ["Myšlenka: Při měření délky zjišťujeme, kolikrát je jednotka délky obsažena v měřeném úseku.", "Měřidla délky:", "Skládací metr", "Svinovací metr", "Pásmo", "Krejčovský metr", "Posuvné měřítko", "Mikrometr", "Přesnost měření:", "Vždy se snažím o co nejpřesnější zjištění hodnoty. Mohou vznikat různé chyby. Pokud chci změřit co nejpřesněji, je dobré měření opakovat a určit aritmetický průměr. Chyby vznikají i chybou měřidla. Ta jsou vždy konstruována s určitou přesností.Pro další výuku budeme určovat chybu měřidla jako polovinu velikosti nejmenšího dílku."], "diagram": "/schemata/fyzika-6-07.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-08", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Hmotnost", "time": "10–20 min", "tag": "6. ročník · téma 8", "explain": "Charakteristika: Hmotnost je fyzikální veličina která popisuje, kolik v sobě mají tělesa hmoty.", "paragraphs": ["Charakteristika: Hmotnost je fyzikální veličina která popisuje, kolik v sobě mají tělesa hmoty.", "Označení veličiny: m  (z anglického mass)", "základní jednotka: kilogram (kg)", "Doporučené násobky a díly kilogramu :", "1 gram (g) – 1 g = 0,001 kg……………...1 kg = 1000 g", "1 centigram (cg) – 1 cg = 0,01 g………...1 g = 100 cg", "1 miligram (mg) – 1 mg = 0,001 g……….1 g = 1000 mg", "1 dekagram (dag) – 1 dag = 0,01 kg…….1 dag = 10 g", "1 metrický cent (q) – 1 q = 100 kg……….1 kg = 0,01 q", "1 tuna (t) – 1 t = 1000 kg………………….1 kg = 0,001 t", "Větu, hmotnost byla osm tisíc gramů, zapíši: m = 8 000 g"], "diagram": "/schemata/fyzika-6-08.svg", "caption": "Postup fyzikálního zkoumání: pozorování, měření a porovnání výsledků.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-09", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Měření hmotnosti", "time": "10–20 min", "tag": "6. ročník · téma 9", "explain": "Při měření hmotnosti často využíváme srovnávací metody, kdy porovnáváme hmotnost známého předmětu (závaží) s hmotností zkoumaného předmětu.", "paragraphs": ["Při měření hmotnosti často využíváme srovnávací metody, kdy porovnáváme hmotnost známého předmětu (závaží) s hmotností zkoumaného předmětu.", "Měřidla hmotnosti se nazývají váhy.", "Druhy vah:", "laboratorní váhy", "obchodní váha", "osobní váha", "přezmen", "závěsné pružinové váhy"], "diagram": "/schemata/fyzika-6-09.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-10", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Objem", "time": "10–20 min", "tag": "6. ročník · téma 10", "explain": "Charakteristika: Objem odvozená fyzikální veličina, která vyjadřuje velikost prostoru vyplněného tělesem.", "paragraphs": ["Charakteristika: Objem odvozená fyzikální veličina, která vyjadřuje velikost prostoru vyplněného tělesem.", "Označení veličiny: Ve fyzice jí zastupuje písmeno V.", "Jednotka:  metr krychlový (m3 )", "Objem může využívat jednotky z matematiky např.  metr krychlový (m3 ), decimetr krychlový (dm3 ), centimetr krychlový (cm3 ), milimetr krychlový (mm3 ).", "Dále můžeme využívat tzv. duté jednotky mililitr (ml), centilitr (cl), decilitr (dl), litr(l), hektolitr (hl).", "Objem kvádru se vypočítá jako součin jeho stran podle vzorce V=a*b*c. Všechny jednotky musí být stejné.", "Převody jednotek:"], "diagram": "/schemata/fyzika-6-10.svg", "caption": "Kapalina v otevřené nádobě: hydrostatický tlak se zvětšuje s hloubkou. Pro měření objemu sledujeme hladinu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-11", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Měření objemu", "time": "10–20 min", "tag": "6. ročník · téma 11", "explain": "Pro měření objemu můžeme využít:", "paragraphs": ["Pro měření objemu můžeme využít:", "Kádinku", "Odměrný válec", "Injekční stříkačku", "Odměrku", "Měření objemu odměrným válcem:", "Zjistíme, jaké jsou na odměrném válci jednotkya jaký maximální objem lze tímto válcem naměřit.", "Určíme hodnotu nejmenšího dílku (objem kapaliny,který odpovídá vzdálenosti mezi sousedními ryskami).", "Nalijeme kapalinu.", "Na stupnici se díváme kolmo (pozor při krajích bývá hladina mírně zvednutá)."], "diagram": "/schemata/fyzika-6-11.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-12", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Čas", "time": "10–20 min", "tag": "6. ročník · téma 12", "explain": "Charakteristika:  Čas označuje dobu, která uplyne mezi dvěma okamžiky.", "paragraphs": ["Charakteristika:  Čas označuje dobu, která uplyne mezi dvěma okamžiky.", "Označení:     t", "Jednotka: sekunda (vteřina)", "Pojem „čas“ může také označovat časový údaj, určitý okamžik na časové ose, která má počátek ve zvoleném nulovém referenčním bodě."], "diagram": "/schemata/fyzika-6-12.svg", "caption": "Postup fyzikálního zkoumání: pozorování, měření a porovnání výsledků.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-13", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Měření času a doby", "time": "10–20 min", "tag": "6. ročník · téma 13", "explain": "Stejně jako všechna jiná měření je stanovování času založeno na srovnávání s jednotkou, v případě času s dobou opakovaného děje.", "paragraphs": ["Stejně jako všechna jiná měření je stanovování času založeno na srovnávání s jednotkou, v případě času s dobou opakovaného děje.", "měřidla:", "Digitální/Analogová", "sluneční hodiny", "kyvadlové hodiny", "quartzové hodiny", "mechanické hodiny"], "diagram": "/schemata/fyzika-6-13.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-14", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Teplota a teplotní stupnice", "time": "10–20 min", "tag": "6. ročník · téma 14", "explain": "Charakteristika: Teplota je fyzikální veličina, která popisuje tepelný stav látky nebo tělesa.", "paragraphs": ["Charakteristika: Teplota je fyzikální veličina, která popisuje tepelný stav látky nebo tělesa.", "Označení veličiny: Ve fyzice jí zastupuje písmeno t", "Jednotka: Základní jednotkou termodynamické teploty je kelvin (K). V běžné praxi používáme také stupeň Celsia (°C).", "Pro měření teploty se využívá několik stupnic:", "Celsiova", "Fahrenheitova (používaná v USA)", "Kelvinova", "Významný bod Kelvinovy stupnice:", "Absolutní nula: 0 K, tedy přibližně −273,15 °C.", "Co je to Absolutní nula?", "nejnižší možná teplota, při níž má soustava nejnižší možnou tepelnou energii.", "V praxi se lze absolutní nule velmi přiblížit, nelze jí však přesně dosáhnout.", "Významné body Celsiovy stupnice:", "0 °C - teplota tání vody", "100 °C - teplota varu vody", "Porovnání Fahrenheitovy, Celsiovy a Kelvinovy stupnice :"], "diagram": "/schemata/fyzika-6-14.svg", "caption": "Samovolná tepelná výměna probíhá od teplejšího tělesa k chladnějšímu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-15", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Roztažnost těles a látek", "time": "10–20 min", "tag": "6. ročník · téma 15", "explain": "Při zahřátí se prodlužuje délka tyčí a drátů. Ochlazením se jejich délka zmenšuje. Tento jev nazýváme délková roztažnost.", "paragraphs": ["Při zahřátí se prodlužuje délka tyčí a drátů. Ochlazením se jejich délka zmenšuje. Tento jev nazýváme délková roztažnost.", "Objem pevných těles, kapalin i plynů se při zahřátí zvětšuje a ochlazení zmenšuje. Tento jev nazýváme objemová roztažnost.", "S tímto chováním je třeba počítat při konstrukcích dálničních mostů, silnic, motorů atp", "Zajímavé odkazy k teplotě 🙂"], "diagram": "/schemata/fyzika-6-15.svg", "caption": "Samovolná tepelná výměna probíhá od teplejšího tělesa k chladnějšímu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-16", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Měření teploty", "time": "10–20 min", "tag": "6. ročník · téma 16", "explain": "Pro měření teploty se využívá teplotoměrů, což je název,  který je správný, ale vy ho určitě znáte jako teploměr 😀", "paragraphs": ["Pro měření teploty se využívá teplotoměrů, což je název,  který je správný, ale vy ho určitě znáte jako teploměr 😀", "Typy teploměrů:", "lékařský", "venkovní", "laboratorní", "bimetalový", "digitální", "Laserový (digitální)", "Pro zaznamenávání teploty využíváme tzv. grafu závislosti teploty na čase. Díky němu můžeme snadno odečítat změny teploty.", "Postup tvorby:", "1. Narýsuji osy.", "2. Na vodorovnou vynesu stupnici času.", "3. Na svislou pak stupnici teploty.", "4. Začnu zaznamenávat hodnoty z tabulky."], "diagram": "/schemata/fyzika-6-16.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-17", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Hustota", "time": "10–20 min", "tag": "6. ročník · téma 17", "explain": "Charakteristika: Hustota je fyzikální veličina, která udává hmotnost jednotkového objemu látky.", "paragraphs": ["Charakteristika: Hustota je fyzikální veličina, která udává hmotnost jednotkového objemu látky.", "Hustota je vlastností látky, která tvoří těleso.", "Označení veličiny: Hustotu zastupuje písmeno ρ (čteme ró).", "Jednotka:  Základní jednotka je kilogram na metr krychlový kgm3.", "další (už ne základní ale tzv. odvozenou) jednotkou je  gcm3.", "Převody jednotek:", "Hustotu měříme hustoměry."], "diagram": "/schemata/fyzika-6-17.svg", "caption": "Při stejném objemu má těleso s větší hmotností větší hustotu. Hustota závisí i na teplotě.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-18", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Výpočet hustoty", "time": "10–20 min", "tag": "6. ročník · téma 18", "explain": "Jaký je postup řešení slovní úlohy ve fyzice:", "paragraphs": ["Jaký je postup řešení slovní úlohy ve fyzice:", "1. Napsat správný fyzikální zápis a převést jednotky, pokud je třeba.", "2. Napsat vzorec a dosadit do něj.", "3. Napsat odpověď.", "Pro zapamatování vzorce můžeme v některých případech využít magického trojúhelníka.", "Hustota: ρ = m / V. Při hmotnosti 54 g a objemu 20 cm³ je hustota 2,7 g/cm³.", "Před dosazením sjednoť jednotky. 1 g/cm³ = 1000 kg/m³."], "diagram": "/schemata/fyzika-6-18.svg", "caption": "Při stejném objemu má těleso s větší hmotností větší hustotu. Hustota závisí i na teplotě.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-19", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Výpočet hmotnosti a objemu z hustoty", "time": "10–20 min", "tag": "6. ročník · téma 19", "explain": "Ze vztahu pro hustotu můžeme vypočítat také hmotnost tělesa nebo jeho objem.", "paragraphs": ["Ze vztahu pro hustotu můžeme vypočítat také hmotnost tělesa nebo jeho objem.", "Základní vztah: ρ = m / V", "Úprava vztahu: m = ρ · V, případně V = m / ρ", "Pozor: Před dosazením musí být jednotky navzájem slučitelné.", "Hustota: ρ — kg/m³ nebo g/cm³.", "Hmotnost: m = ρ · V — kg nebo g.", "Objem: V = m / ρ — m³ nebo cm³.", "Příklad: Hliníkové těleso má objem 20 cm³ a hustotu 2,7 g/cm³. Jeho hmotnost je m = ρ · V = 2,7 · 20 = 54 g."], "diagram": "/schemata/fyzika-6-19.svg", "caption": "Při stejném objemu má těleso s větší hmotností větší hustotu. Hustota závisí i na teplotě.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-20", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Elektrické vlastnosti látek", "time": "10–20 min", "tag": "6. ročník · téma 20", "explain": "Tělesa lze třením nebo dotykem zelektrovat. Elektrický náboj může být kladný nebo záporný.", "paragraphs": ["Tělesa lze třením nebo dotykem zelektrovat. Elektrický náboj může být kladný nebo záporný.", "Stavba atomu: Proton má kladný náboj, elektron záporný náboj a neutron je elektricky neutrální.", "Iont: Kation vznikne ztrátou elektronů, anion přijetím elektronů.", "Působení nábojů: Stejné náboje se odpuzují, opačné náboje se přitahují.", "Elektrické pole: Nachází se kolem elektricky nabitého tělesa a působí na další náboje.", "Pokus nebo pozorování: Třením nafouknutého balónku o vlasy ověřte, že zelektrované těleso může přitahovat drobné papírky."], "diagram": "/schemata/fyzika-6-20.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-6-21", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Magnetické vlastnosti látek", "time": "10–20 min", "tag": "6. ročník · téma 21", "explain": "Magnet působí na některé látky magnetickou silou. Každý magnet má severní a jižní pól.", "paragraphs": ["Magnet působí na některé látky magnetickou silou. Každý magnet má severní a jižní pól.", "Póly magnetu: Souhlasné póly se odpuzují, nesouhlasné se přitahují.", "Feromagnetické látky: Silně reagují na magnetické pole, například železo, nikl a kobalt.", "Magnetizace: Předmět z feromagnetické látky se může v magnetickém poli dočasně nebo trvale zmagnetovat.", "Magnetické pole Země: Kompas se orientuje přibližně ve směru sever–jih.", "Pokus nebo pozorování: Položte nad tyčový magnet papír a opatrně nasypte železné piliny. Sledujte obraz magnetického pole."], "diagram": "/schemata/fyzika-6-21.svg", "caption": "Magnetické pole tyčového magnetu. Vnější směr siločar je od severního k jižnímu pólu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-22", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Síla a vzájemné působení těles", "time": "10–20 min", "tag": "6. ročník · téma 22", "explain": "Síla popisuje vzájemné působení těles. Může měnit pohyb tělesa nebo jeho tvar.", "paragraphs": ["Síla popisuje vzájemné působení těles. Může měnit pohyb tělesa nebo jeho tvar.", "Označení: F", "Jednotka: newton (N)", "Měřidlo: siloměr", "Znázornění: Sílu znázorňujeme orientovanou úsečkou. Rozhoduje velikost, směr, orientace a působiště.", "Síla: F — newton N.", "Gravitační síla: Fg — směřuje ke středu Země.", "Pokus nebo pozorování: Změřte siloměrem sílu potřebnou ke zvednutí různých těles. Hodnoty zapište v newtonech."], "diagram": "/schemata/fyzika-6-22.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-23", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Gravitační síla a gravitační pole Země", "time": "10–20 min", "tag": "6. ročník · téma 23", "explain": "Země přitahuje všechna tělesa gravitační silou. V blízkosti povrchu Země směřuje tato síla svisle dolů.", "paragraphs": ["Země přitahuje všechna tělesa gravitační silou. V blízkosti povrchu Země směřuje tato síla svisle dolů.", "Gravitační pole: Prostor, ve kterém působí gravitační síla.", "Závislost: Čím větší je hmotnost tělesa, tím větší gravitační síla na něj působí.", "Přibližný vztah: Fg = m · g, kde g ≈ 10 N/kg.", "Fg = m · g", "Příklad: Na těleso o hmotnosti 2 kg působí u povrchu Země gravitační síla přibližně 20 N."], "diagram": "/schemata/fyzika-6-23.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-24", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Opakované měření a aritmetický průměr", "time": "10–20 min", "tag": "6. ročník · téma 24", "explain": "Každé měření je zatíženo nejistotou. Spolehlivější výsledek získáme opakovaným měřením a výpočtem průměru.", "paragraphs": ["Každé měření je zatíženo nejistotou. Spolehlivější výsledek získáme opakovaným měřením a výpočtem průměru.", "Zápis výsledku: Vždy zapisujeme číselnou hodnotu i jednotku.", "Rozlišení měřidla: Nejmenší dílek stupnice určuje, s jakou přesností lze hodnotu odečíst.", "Aritmetický průměr: Naměřené hodnoty sečteme a vydělíme jejich počtem.", "x̄ = (x₁ + x₂ + … + xₙ) / n", "Příklad: Délky 12,1 cm; 12,3 cm a 12,2 cm mají průměr 12,2 cm."], "diagram": "/schemata/fyzika-6-24.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-6-25", "subject": "fyzika", "stage": "2", "grade": "6", "title": "Měření objemu pevného tělesa", "time": "10–20 min", "tag": "6. ročník · téma 25", "explain": "Objem pravidelného tělesa vypočítáme z jeho rozměrů. Objem nepravidelného tělesa lze určit ponořením do kapaliny v odměrném válci.", "paragraphs": ["Objem pravidelného tělesa vypočítáme z jeho rozměrů. Objem nepravidelného tělesa lze určit ponořením do kapaliny v odměrném válci.", "Postup vytlačením kapaliny: Odečteme počáteční objem V₁, ponoříme těleso, odečteme V₂ a vypočítáme V = V₂ − V₁.", "Odečet: Hladinu odečítáme v úrovni očí a u vody podle dolního okraje menisku.", "V tělesa = V₂ − V₁", "Pokus nebo pozorování: Určete objem kamínku pomocí odměrného válce. Výsledek zapište v ml i cm³."], "diagram": "/schemata/fyzika-6-25.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 6. ročníku", "url": null}]}, {"id": "fyzika-7-01", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Klid a pohyb tělesa", "time": "10–20 min", "tag": "7. ročník · téma 1", "explain": "O tom, zda je těleso v klidu nebo v pohybu, rozhodujeme vždy vzhledem k jinému tělesu – vztažnému tělesu.", "paragraphs": ["O tom, zda je těleso v klidu nebo v pohybu, rozhodujeme vždy vzhledem k jinému tělesu – vztažnému tělesu.", "Relativnost pohybu: Cestující sedí vzhledem k vagónu, ale pohybuje se vzhledem ke krajině.", "Poloha: Určujeme ji vzhledem ke zvolenému vztažnému tělesu.", "Pokus nebo pozorování: Pozorujte předměty z jedoucího autobusu a určete, vůči čemu jsou v klidu a vůči čemu v pohybu."], "diagram": "/schemata/fyzika-7-01.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-02", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Trajektorie, dráha a druhy pohybu", "time": "10–20 min", "tag": "7. ročník · téma 2", "explain": "Trajektorie je čára, kterou při pohybu opisuje bod tělesa. Dráha je délka trajektorie.", "paragraphs": ["Trajektorie je čára, kterou při pohybu opisuje bod tělesa. Dráha je délka trajektorie.", "Podle trajektorie: Pohyb přímočarý nebo křivočarý.", "Podle změny polohy částí tělesa: Pohyb posuvný nebo otáčivý.", "Podle rychlosti: Pohyb rovnoměrný nebo nerovnoměrný.", "Dráha: s — metr m.", "Čas: t — sekunda s.", "Rychlost: v — metr za sekundu m/s."], "diagram": "/schemata/fyzika-7-02.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-03", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Rychlost pohybu", "time": "10–20 min", "tag": "7. ročník · téma 3", "explain": "Rychlost vyjadřuje, jakou dráhu těleso urazí za jednotku času.", "paragraphs": ["Rychlost vyjadřuje, jakou dráhu těleso urazí za jednotku času.", "Rovnoměrný pohyb: Těleso urazí za stejné časové intervaly stejné dráhy.", "Nerovnoměrný pohyb: Rychlost se mění; často počítáme průměrnou rychlost.", "Rychlost: v = s / t — m/s nebo km/h.", "Dráha: s = v · t — m nebo km.", "Čas: t = s / v — s nebo h.", "v = s / t", "Příklad: Cyklista ujede 12 km za 0,5 h. Jeho průměrná rychlost je 12 / 0,5 = 24 km/h."], "diagram": "/schemata/fyzika-7-03.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-04", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Převody rychlosti a graf pohybu", "time": "10–20 min", "tag": "7. ročník · téma 4", "explain": "Rychlost lze vyjadřovat v m/s i km/h. Graf závislosti dráhy na čase ukazuje, jak se poloha tělesa mění.", "paragraphs": ["Rychlost lze vyjadřovat v m/s i km/h. Graf závislosti dráhy na čase ukazuje, jak se poloha tělesa mění.", "Převod: 1 m/s = 3,6 km/h; z m/s na km/h násobíme 3,6, opačně dělíme 3,6.", "Graf s–t: Vodorovná osa znázorňuje čas, svislá osa dráhu. Strmější přímka znamená vyšší rychlost.", "Příklad: 72 km/h = 72 : 3,6 = 20 m/s."], "diagram": "/schemata/fyzika-7-04.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-05", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Síla a její znázornění", "time": "10–20 min", "tag": "7. ročník · téma 5", "explain": "Síla je vektorová fyzikální veličina. Může měnit rychlost, směr pohybu nebo tvar tělesa.", "paragraphs": ["Síla je vektorová fyzikální veličina. Může měnit rychlost, směr pohybu nebo tvar tělesa.", "Označení: F", "Jednotka: newton (N)", "Znázornění: Orientovaná úsečka určuje velikost, směr, orientaci a působiště síly.", "Síla: F — newton N.", "Gravitační zrychlení: g — přibližně 10 N/kg."], "diagram": "/schemata/fyzika-7-05.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-06", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Gravitační síla a tíha tělesa", "time": "10–20 min", "tag": "7. ročník · téma 6", "explain": "Gravitační síla je síla, kterou Země působí na těleso. Tíha je síla, kterou těleso působí na podložku nebo závěs.", "paragraphs": ["Gravitační síla je síla, kterou Země působí na těleso. Tíha je síla, kterou těleso působí na podložku nebo závěs.", "Gravitační síla: Působí na těleso i při volném pádu.", "Tíha: Nevzniká při beztížném stavu; působí na podložku nebo závěs.", "Fg = m · g", "Příklad: Na těleso o hmotnosti 5 kg působí gravitační síla přibližně 50 N."], "diagram": "/schemata/fyzika-7-06.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-07", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Skládání sil, rovnováha a těžiště", "time": "10–20 min", "tag": "7. ročník · téma 7", "explain": "Výslednice nahrazuje účinek několika sil jedinou silou.", "paragraphs": ["Výslednice nahrazuje účinek několika sil jedinou silou.", "Stejný směr: Velikosti sil se sčítají.", "Opačný směr: Velikosti sil se odečítají; výslednice má směr větší síly.", "Rovnováha sil: Výslednice je nulová.", "Těžiště: Bod, ve kterém můžeme uvažovat působení gravitační síly.", "Příklad: Síly 8 N doprava a 3 N doleva mají výslednici 5 N doprava.", "Pokus nebo pozorování: Najděte těžiště pravítka nebo vystřiženého kartonu vyvažováním."], "diagram": "/schemata/fyzika-7-07.svg", "caption": "Postup fyzikálního zkoumání: pozorování, měření a porovnání výsledků.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-08", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Newtonovy pohybové zákony", "time": "10–20 min", "tag": "7. ročník · téma 8", "explain": "Newtonovy zákony popisují vztah mezi silami a pohybem těles. V sedmém ročníku slouží jako návazné vysvětlení situací, které běžně pozorujeme.", "paragraphs": ["Newtonovy zákony popisují vztah mezi silami a pohybem těles. V sedmém ročníku slouží jako návazné vysvětlení situací, které běžně pozorujeme.", "Zákon setrvačnosti: Těleso zůstává v klidu nebo v rovnoměrném přímočarém pohybu, pokud je výslednice sil působících na těleso nulová.", "Zákon síly: Změna pohybu je tím větší, čím větší je výsledná síla; těleso s větší hmotností mění svůj pohyb obtížněji.", "Zákon akce a reakce: Působí-li jedno těleso na druhé silou, působí druhé současně na první stejně velkou silou opačného směru. Síly působí na různá tělesa.", "Příklad: Při prudkém zabrzdění autobusu mají cestující vlivem setrvačnosti tendenci pokračovat v pohybu vpřed.", "Pokus nebo pozorování: Položte minci na kartu nad sklenicí. Rychlým vodorovným trhnutím kartu odstraňte a sledujte projev setrvačnosti mince."], "diagram": "/schemata/fyzika-7-08.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-09", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Otáčivý účinek síly a páka", "time": "10–20 min", "tag": "7. ročník · téma 9", "explain": "Otáčivý účinek síly závisí na velikosti síly a na kolmé vzdálenosti osy otáčení od přímky působení síly.", "paragraphs": ["Otáčivý účinek síly závisí na velikosti síly a na kolmé vzdálenosti osy otáčení od přímky působení síly.", "Rameno síly: Kolmá vzdálenost osy otáčení od přímky působení síly.", "Moment síly: Součin velikosti síly a ramene síly.", "Rovnováha páky: Moment síly na jedné straně se rovná momentu síly na druhé straně.", "Moment síly: M = F · a — newtonmetr N·m.", "Rovnováha páky: F₁a₁ = F₂a₂ — momenty jsou stejné."], "diagram": "/schemata/fyzika-7-09.svg", "caption": "Rovnováha páky: opačné momenty sil jsou stejně velké. Ramena jsou kolmé vzdálenosti od osy k přímkám sil.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-10", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Kladka", "time": "10–20 min", "tag": "7. ročník · téma 10", "explain": "Pevná kladka mění směr síly, ale její velikost ideálně nemění. Volná kladka může potřebnou sílu zmenšit.", "paragraphs": ["Pevná kladka mění směr síly, ale její velikost ideálně nemění. Volná kladka může potřebnou sílu zmenšit.", "Pevná kladka: Umožní táhnout dolů a zvedat břemeno nahoru.", "Volná kladka: Břemeno nesou dvě části lana; potřebná síla je ideálně poloviční.", "Kladkostroj: Kombinuje více kladek.", "Pokus nebo pozorování: Sestavte jednoduchou pevnou kladku a porovnejte směr působící síly."], "diagram": "/schemata/fyzika-7-10.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-11", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Tlak v pevných látkách", "time": "10–20 min", "tag": "7. ročník · téma 11", "explain": "Tlak vyjadřuje, jak velká tlaková síla působí na jednotku plochy.", "paragraphs": ["Tlak vyjadřuje, jak velká tlaková síla působí na jednotku plochy.", "Zvětšení tlaku: Zvětšíme sílu nebo zmenšíme plochu.", "Zmenšení tlaku: Zmenšíme sílu nebo zvětšíme plochu.", "Tlak: p = F / S — pascal Pa.", "Tlaková síla: F = p · S — newton N.", "Plocha: S = F / p — metr čtvereční m².", "p = F / S", "Příklad: Síla 200 N působí na plochu 0,5 m². Tlak je 400 Pa."], "diagram": "/schemata/fyzika-7-11.svg", "caption": "Kapalina v otevřené nádobě: hydrostatický tlak se zvětšuje s hloubkou. Pro měření objemu sledujeme hladinu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-12", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Třecí síla", "time": "10–20 min", "tag": "7. ročník · téma 12", "explain": "Třecí síla působí proti pohybu nebo proti snaze uvést těleso do pohybu.", "paragraphs": ["Třecí síla působí proti pohybu nebo proti snaze uvést těleso do pohybu.", "Závislost: Roste s přítlačnou silou a závisí na materiálu a drsnosti povrchů.", "Zvětšení tření: Hrubší povrch, větší přítlak, protiskluzová úprava.", "Zmenšení tření: Mazání, ložiska, hladší povrch.", "Pokus nebo pozorování: Táhněte stejný kvádr siloměrem po různých površích a porovnejte třecí sílu."], "diagram": "/schemata/fyzika-7-12.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-13", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Pascalův zákon a hydraulická zařízení", "time": "10–20 min", "tag": "7. ročník · téma 13", "explain": "Tlak vyvolaný v uzavřené kapalině se přenáší všemi směry stejně.", "paragraphs": ["Tlak vyvolaný v uzavřené kapalině se přenáší všemi směry stejně.", "Pascalův zákon: Změna tlaku se přenese do všech míst kapaliny.", "Využití: Hydraulický lis, zvedák a brzdy.", "Podmínka: V ideálním zařízení platí p₁ = p₂.", "Tlak: p = F / S — Pa.", "Hydraulika: F₁/S₁ = F₂/S₂ — větší píst dává větší sílu."], "diagram": "/schemata/fyzika-7-13.svg", "caption": "Postup fyzikálního zkoumání: pozorování, měření a porovnání výsledků.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-14", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Hydrostatický tlak", "time": "10–20 min", "tag": "7. ročník · téma 14", "explain": "Kapalina v gravitačním poli působí tlakem. Hydrostatický tlak roste s hloubkou, hustotou kapaliny a gravitačním zrychlením.", "paragraphs": ["Kapalina v gravitačním poli působí tlakem. Hydrostatický tlak roste s hloubkou, hustotou kapaliny a gravitačním zrychlením.", "Závislost: Nezávisí na tvaru nádoby, ale na hloubce a hustotě kapaliny.", "Směr působení: Kapalina tlačí na dno i stěny nádoby.", "pₕ = h · ρ · g", "Příklad: Ve vodě v hloubce 2 m je hydrostatický tlak přibližně 20 000 Pa."], "diagram": "/schemata/fyzika-7-14.svg", "caption": "Kapalina v otevřené nádobě: hydrostatický tlak se zvětšuje s hloubkou. Pro měření objemu sledujeme hladinu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-15", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Spojené nádoby", "time": "10–20 min", "tag": "7. ročník · téma 15", "explain": "Spojené nádoby mají pod hladinou vzájemně propojený prostor. Je-li v nich stejná kapalina a působí na hladiny stejný vnější tlak, ustálí se hladiny ve stejné výšce.", "paragraphs": ["Spojené nádoby mají pod hladinou vzájemně propojený prostor. Je-li v nich stejná kapalina a působí na hladiny stejný vnější tlak, ustálí se hladiny ve stejné výšce.", "Vysvětlení: V téže hloubce musí být v klidné propojené kapalině stejný tlak.", "Různé kapaliny: Kapalina s větší hustotou vytvoří nižší sloupec, kapalina s menší hustotou vyšší sloupec.", "Využití: Vodovod, hadicová vodováha, vodoznak a některé tlakoměry.", "Pokus nebo pozorování: Spojte dvě průhledné nádoby hadičkou, naplňte je obarvenou vodou a porovnejte výšku hladin při různém tvaru nádob."], "diagram": "/schemata/fyzika-7-15.svg", "caption": "Kapalina v otevřené nádobě: hydrostatický tlak se zvětšuje s hloubkou. Pro měření objemu sledujeme hladinu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-16", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Hustota kapaliny a teplota", "time": "10–20 min", "tag": "7. ročník · téma 16", "explain": "Při zahřívání se většina kapalin rozpíná. Jejich hmotnost zůstává stejná, objem roste, a proto hustota obvykle klesá.", "paragraphs": ["Při zahřívání se většina kapalin rozpíná. Jejich hmotnost zůstává stejná, objem roste, a proto hustota obvykle klesá.", "Proudění: Teplejší kapalina s menší hustotou stoupá, chladnější s větší hustotou klesá.", "Anomálie vody: Voda má největší hustotu přibližně při 4 °C. Tato vlastnost pomáhá vodním organismům přežít zimu.", "Využití: Proudění při ohřevu vody, vytápění místností a vznik proudů v atmosféře.", "ρ = m / V", "Pokus nebo pozorování: Kápněte obarvenou teplou a studenou vodu do průhledné nádoby a sledujte rozdílné proudění."], "diagram": "/schemata/fyzika-7-16.svg", "caption": "Při stejném objemu má těleso s větší hmotností větší hustotu. Hustota závisí i na teplotě.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-17", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Vztlaková síla a Archimédův zákon", "time": "10–20 min", "tag": "7. ročník · téma 17", "explain": "Na těleso ponořené do kapaliny působí svisle vzhůru vztlaková síla.", "paragraphs": ["Na těleso ponořené do kapaliny působí svisle vzhůru vztlaková síla.", "Archimédův zákon: Vztlaková síla se rovná tíze kapaliny tělesem vytlačené.", "Chování tělesa: Ponoří se, vznáší se nebo plove podle porovnání gravitační a vztlakové síly.", "Fᵥz = ρ · V · g", "Pokus nebo pozorování: Porovnejte zdánlivou tíhu tělesa ve vzduchu a po ponoření do vody."], "diagram": "/schemata/fyzika-7-17.svg", "caption": "Kapalina v otevřené nádobě: hydrostatický tlak se zvětšuje s hloubkou. Pro měření objemu sledujeme hladinu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-18", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Atmosférický tlak", "time": "10–20 min", "tag": "7. ročník · téma 18", "explain": "Atmosféra má hmotnost a působí tlakem na všechna tělesa.", "paragraphs": ["Atmosféra má hmotnost a působí tlakem na všechna tělesa.", "Normální tlak: Přibližně 101 325 Pa u hladiny moře.", "Změna s výškou: S rostoucí nadmořskou výškou tlak klesá.", "Měřidla: Barometr měří atmosférický tlak, manometr tlak plynu v nádobě.", "Pokus nebo pozorování: Překryjte sklenici naplněnou vodou kartou a opatrně ji otočte. Sledujte účinek atmosférického tlaku."], "diagram": "/schemata/fyzika-7-18.svg", "caption": "Kapalina v otevřené nádobě: hydrostatický tlak se zvětšuje s hloubkou. Pro měření objemu sledujeme hladinu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-19", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Meteorologie a změny počasí", "time": "10–20 min", "tag": "7. ročník · téma 19", "explain": "Meteorologie zkoumá stav a děje v atmosféře. Pro předpověď počasí se sleduje více veličin současně.", "paragraphs": ["Meteorologie zkoumá stav a děje v atmosféře. Pro předpověď počasí se sleduje více veličin současně.", "Atmosférický tlak: Měří se barometrem; tlakové výše bývají spojeny se stabilnějším počasím, tlakové níže s oblačností a srážkami.", "Teplota a vlhkost: Ovlivňují vznik oblaků, mlhy, rosy a jinovatky.", "Vítr: Popisujeme směrem a rychlostí; měří se anemometrem.", "Srážky: Množství se udává obvykle v milimetrech; 1 mm odpovídá 1 litru vody na 1 m².", "Pokus nebo pozorování: Po dobu jednoho týdne zapisujte teplotu, tlak a stav oblohy. Hledejte souvislost mezi změnou tlaku a počasím."], "diagram": "/schemata/fyzika-7-19.svg", "caption": "Postup fyzikálního zkoumání: pozorování, měření a porovnání výsledků.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-7-20", "subject": "fyzika", "stage": "2", "grade": "7", "title": "Přetlak, podtlak a vztlak v plynech", "time": "10–20 min", "tag": "7. ročník · téma 20", "explain": "Tlak plynu v uzavřené nádobě porovnáváme s atmosférickým tlakem.", "paragraphs": ["Tlak plynu v uzavřené nádobě porovnáváme s atmosférickým tlakem.", "Přetlak: Tlak uvnitř je větší než atmosférický tlak.", "Podtlak: Tlak uvnitř je menší než atmosférický tlak.", "Vztlak v atmosféře: Těleso je nadlehčováno silou rovnou tíze vytlačeného vzduchu; využívají toho balóny a vzducholodě."], "diagram": "/schemata/fyzika-7-20.svg", "caption": "Kapalina v otevřené nádobě: hydrostatický tlak se zvětšuje s hloubkou. Pro měření objemu sledujeme hladinu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 7. ročníku", "url": null}]}, {"id": "fyzika-8-01", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Práce", "time": "10–20 min", "tag": "8. ročník · téma 1", "explain": "Mechanická práce se koná, když síla posouvá těleso. Pro stálou sílu ve směru pohybu platí W = F · s. Jednotkou je joule (J). Držet batoh bez pohybu je pro svaly namáhavé, ale mechanická práce na nehybném batohu je nulová.", "paragraphs": ["Mechanická práce se koná, když síla posouvá těleso. Pro stálou sílu ve směru pohybu platí W = F · s. Jednotkou je joule (J). Držet batoh bez pohybu je pro svaly namáhavé, ale mechanická práce na nehybném batohu je nulová.", "Zvednutí tělesa silou 20 N o 2 m: W = 20 · 2 = 40 J."], "diagram": "/schemata/fyzika-8-01.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-02", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Výkon a účinnost", "time": "10–20 min", "tag": "8. ročník · téma 2", "explain": "Výkon vyjadřuje práci vykonanou za jednotku času: P = W / t. Jednotkou je watt (W). Účinnost je poměr užitečné vydané energie k dodané energii; při vyjádření v procentech násobíme poměr stem. Reálný stroj část energie přemění například na vnitřní energii.", "paragraphs": ["Výkon vyjadřuje práci vykonanou za jednotku času: P = W / t. Jednotkou je watt (W). Účinnost je poměr užitečné vydané energie k dodané energii; při vyjádření v procentech násobíme poměr stem. Reálný stroj část energie přemění například na vnitřní energii.", "Stroj vykoná 600 J za 3 s: P = 200 W. Z dodaných 1000 J využije 600 J: účinnost je 60 %."], "diagram": "/schemata/fyzika-8-02.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-03", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Pohybová a polohová energie", "time": "10–20 min", "tag": "8. ročník · téma 3", "explain": "Pohybující se těleso má pohybovou energii, která roste s hmotností a s druhou mocninou rychlosti. Polohová energie v gravitačním poli závisí na zvolené nulové výšce. U zemského povrchu počítáme Ep = m · g · h. Energii udáváme v joulech.", "paragraphs": ["Pohybující se těleso má pohybovou energii, která roste s hmotností a s druhou mocninou rychlosti. Polohová energie v gravitačním poli závisí na zvolené nulové výšce. U zemského povrchu počítáme Ep = m · g · h. Energii udáváme v joulech.", "Kniha o hmotnosti 1 kg ve výšce 2 m má vůči podlaze přibližně 20 J polohové energie."], "diagram": "/schemata/fyzika-8-03.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-04", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Přeměny a zachování energie", "time": "10–20 min", "tag": "8. ročník · téma 4", "explain": "Energie se může přeměňovat mezi různými formami. V uzavřené soustavě se celková energie zachovává. Při pádu se polohová energie mění na pohybovou; při dopadu se část energie projeví deformací, zvukem a zahřátím.", "paragraphs": ["Energie se může přeměňovat mezi různými formami. V uzavřené soustavě se celková energie zachovává. Při pádu se polohová energie mění na pohybovou; při dopadu se část energie projeví deformací, zvukem a zahřátím.", "Na houpačce je v nejnižší poloze největší rychlost; v krajní poloze se na okamžik zastaví."], "diagram": "/schemata/fyzika-8-04.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-05", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Vnitřní energie a teplo", "time": "10–20 min", "tag": "8. ročník · téma 5", "explain": "Vnitřní energie souvisí s neuspořádaným pohybem částic a jejich vzájemným působením. Změníme ji prací nebo předáním tepla. Teplo je energie předaná kvůli rozdílu teplot; teplota a teplo nejsou stejná veličina.", "paragraphs": ["Vnitřní energie souvisí s neuspořádaným pohybem částic a jejich vzájemným působením. Změníme ji prací nebo předáním tepla. Teplo je energie předaná kvůli rozdílu teplot; teplota a teplo nejsou stejná veličina.", "Při tření dlaní se vnitřní energie mění prací. Hrnek čaje ji okolí předává tepelnou výměnou."], "diagram": "/schemata/fyzika-8-05.svg", "caption": "Částicový model skupenství. Body představují částice, nikoli jejich skutečný tvar či velikost.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-06", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Tepelná výměna", "time": "10–20 min", "tag": "8. ročník · téma 6", "explain": "Tepelná energie přechází samovolně z teplejšího tělesa na chladnější. Vedení probíhá například v kovové lžičce, proudění v kapalinách a plynech a záření může přenášet energii i vakuem. Izolace tepelný přenos zpomaluje.", "paragraphs": ["Tepelná energie přechází samovolně z teplejšího tělesa na chladnější. Vedení probíhá například v kovové lžičce, proudění v kapalinách a plynech a záření může přenášet energii i vakuem. Izolace tepelný přenos zpomaluje.", "Slunce ohřívá Zemi zářením; vzduch nad topením stoupá díky proudění."], "diagram": "/schemata/fyzika-8-06.svg", "caption": "Samovolná tepelná výměna probíhá od teplejšího tělesa k chladnějšímu.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-07", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Měrná tepelná kapacita", "time": "10–20 min", "tag": "8. ročník · téma 7", "explain": "Bez změny skupenství platí pro ohřev Q = m · c · Δt. Měrná tepelná kapacita c říká, kolik energie je třeba k ohřátí kilogramu látky o jeden stupeň. Pro vodu používáme přibližně 4200 J/(kg · °C).", "paragraphs": ["Bez změny skupenství platí pro ohřev Q = m · c · Δt. Měrná tepelná kapacita c říká, kolik energie je třeba k ohřátí kilogramu látky o jeden stupeň. Pro vodu používáme přibližně 4200 J/(kg · °C).", "Ohřát 0,5 kg vody o 10 °C vyžaduje přibližně 21 000 J, pokud zanedbáme ztráty."], "diagram": "/schemata/fyzika-8-07.svg", "caption": "Samovolná tepelná výměna probíhá od teplejšího tělesa k chladnějšímu.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-08", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Tání, tuhnutí, vypařování a var", "time": "10–20 min", "tag": "8. ročník · téma 8", "explain": "Při tání přechází pevná látka do kapalného skupenství; při tuhnutí obráceně. Vypařování probíhá z povrchu kapaliny i pod teplotou varu. Při varu vznikají bubliny páry v celém objemu. Teplota varu závisí na tlaku.", "paragraphs": ["Při tání přechází pevná látka do kapalného skupenství; při tuhnutí obráceně. Vypařování probíhá z povrchu kapaliny i pod teplotou varu. Při varu vznikají bubliny páry v celém objemu. Teplota varu závisí na tlaku.", "Voda za běžného atmosférického tlaku vře přibližně při 100 °C. Mokré prádlo schne i při 20 °C."], "diagram": "/schemata/fyzika-8-08.svg", "caption": "Samovolná tepelná výměna probíhá od teplejšího tělesa k chladnějšímu.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-09", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Kapalnění, sublimace a voda v přírodě", "time": "10–20 min", "tag": "8. ročník · téma 9", "explain": "Kapalnění neboli kondenzace je změna plynu na kapalinu. Sublimace je přímý přechod pevné látky do plynného skupenství, desublimace je opačná změna. Při kondenzaci se energie uvolňuje do okolí.", "paragraphs": ["Kapalnění neboli kondenzace je změna plynu na kapalinu. Sublimace je přímý přechod pevné látky do plynného skupenství, desublimace je opačná změna. Při kondenzaci se energie uvolňuje do okolí.", "Na studené sklenici se sráží vodní pára ze vzduchu. Námraza může vzniknout desublimací."], "diagram": "/schemata/fyzika-8-09.svg", "caption": "Samovolná tepelná výměna probíhá od teplejšího tělesa k chladnějšímu.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-10", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Elektrický obvod a elektrický proud", "time": "10–20 min", "tag": "8. ročník · téma 10", "explain": "Proud je uspořádaný pohyb elektricky nabitých částic. V jednoduchém obvodu musí být zdroj, vodiče, spotřebič a uzavřená vodivá cesta. Proud I měříme v ampérech. Dohodnutý směr proudu vně zdroje je od kladného pólu k zápornému.", "paragraphs": ["Proud je uspořádaný pohyb elektricky nabitých částic. V jednoduchém obvodu musí být zdroj, vodiče, spotřebič a uzavřená vodivá cesta. Proud I měříme v ampérech. Dohodnutý směr proudu vně zdroje je od kladného pólu k zápornému.", "Rozepnutý vypínač přeruší cestu a žárovka zhasne. Zkoušej pouze školní nízkonapěťové bateriové obvody."], "diagram": "/schemata/fyzika-8-10.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}, {"title": "RVP · elektřina a magnetismus", "url": "https://prohlednout.rvp.cz/zakladni-vzdelavani/vzdelavaci-oblasti/cap/fyz/elektrina-a-magnetismus"}]}, {"id": "fyzika-8-11", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Elektrické napětí a měření proudu", "time": "10–20 min", "tag": "8. ročník · téma 11", "explain": "Napětí U mezi dvěma místy vyjadřuje rozdíl elektrických potenciálů. Jednotkou je volt. Voltmetr připojujeme paralelně mezi dvě místa, ampérmetr sériově do větve. Ampérmetr nikdy nepřipojujeme přímo mezi póly zdroje.", "paragraphs": ["Napětí U mezi dvěma místy vyjadřuje rozdíl elektrických potenciálů. Jednotkou je volt. Voltmetr připojujeme paralelně mezi dvě místa, ampérmetr sériově do větve. Ampérmetr nikdy nepřipojujeme přímo mezi póly zdroje.", "Baterie může mít napětí 1,5 V; tento údaj sám o sobě neurčuje proud ve spotřebiči."], "diagram": "/schemata/fyzika-8-11.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}, {"title": "RVP · elektřina a magnetismus", "url": "https://prohlednout.rvp.cz/zakladni-vzdelavani/vzdelavaci-oblasti/cap/fyz/elektrina-a-magnetismus"}]}, {"id": "fyzika-8-12", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Elektrický odpor a Ohmův zákon", "time": "10–20 min", "tag": "8. ročník · téma 12", "explain": "Odpor R udává, jak vodič za daných podmínek omezuje proud; jednotkou je ohm (Ω). U ohmického vodiče při stálé teplotě platí U = R · I. Odpor závisí na materiálu, délce, průřezu a teplotě.", "paragraphs": ["Odpor R udává, jak vodič za daných podmínek omezuje proud; jednotkou je ohm (Ω). U ohmického vodiče při stálé teplotě platí U = R · I. Odpor závisí na materiálu, délce, průřezu a teplotě.", "Při napětí 6 V a odporu 30 Ω teče proud I = 6 / 30 = 0,2 A."], "diagram": "/schemata/fyzika-8-12.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}, {"title": "RVP · elektřina a magnetismus", "url": "https://prohlednout.rvp.cz/zakladni-vzdelavani/vzdelavaci-oblasti/cap/fyz/elektrina-a-magnetismus"}]}, {"id": "fyzika-8-13", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Sériové a paralelní zapojení", "time": "10–20 min", "tag": "8. ročník · téma 13", "explain": "Při sériovém zapojení protéká součástkami stejný proud a napětí se rozděluje. Odpory se sčítají. Paralelní větve mají stejné napětí a proud se mezi větve rozděluje. Přerušení jedné větve nemusí odpojit ostatní.", "paragraphs": ["Při sériovém zapojení protéká součástkami stejný proud a napětí se rozděluje. Odpory se sčítají. Paralelní větve mají stejné napětí a proud se mezi větve rozděluje. Přerušení jedné větve nemusí odpojit ostatní.", "Dva odpory 10 Ω v sérii mají 20 Ω. Paralelně mají dohromady 5 Ω."], "diagram": "/schemata/fyzika-8-13.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}, {"title": "RVP · elektřina a magnetismus", "url": "https://prohlednout.rvp.cz/zakladni-vzdelavani/vzdelavaci-oblasti/cap/fyz/elektrina-a-magnetismus"}]}, {"id": "fyzika-8-14", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Elektrická práce a příkon", "time": "10–20 min", "tag": "8. ročník · téma 14", "explain": "Elektrická energie při stálém napětí a proudu je E = U · I · t, příkon P = U · I. Kilowatthodina je jednotka energie, ne výkonu. 1 kWh = 3,6 MJ. Úsporu posoudíme podle příkonu i délky používání.", "paragraphs": ["Elektrická energie při stálém napětí a proudu je E = U · I · t, příkon P = U · I. Kilowatthodina je jednotka energie, ne výkonu. 1 kWh = 3,6 MJ. Úsporu posoudíme podle příkonu i délky používání.", "Spotřebič s příkonem 100 W za 2 hodiny spotřebuje 0,2 kWh."], "diagram": "/schemata/fyzika-8-14.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}, {"title": "RVP · elektřina a magnetismus", "url": "https://prohlednout.rvp.cz/zakladni-vzdelavani/vzdelavaci-oblasti/cap/fyz/elektrina-a-magnetismus"}]}, {"id": "fyzika-8-15", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Zvuk a kmitání", "time": "10–20 min", "tag": "8. ročník · téma 15", "explain": "Zvuk vzniká kmitáním zdroje a šíří se prostředím jako mechanické vlnění. Ve vakuu se nešíří. Frekvence f určuje počet kmitů za sekundu a udává se v hertzech. Vyšší frekvence odpovídá vyššímu tónu.", "paragraphs": ["Zvuk vzniká kmitáním zdroje a šíří se prostředím jako mechanické vlnění. Ve vakuu se nešíří. Frekvence f určuje počet kmitů za sekundu a udává se v hertzech. Vyšší frekvence odpovídá vyššímu tónu.", "Kmitající pravítko přes hranu stolu vydává zvuk; kratší volná část obvykle vytvoří vyšší tón."], "diagram": "/schemata/fyzika-8-15.svg", "caption": "Graf kmitání v čase. Vzduchem se zvuk šíří jako podélné vlnění; tato křivka neukazuje tvar vzduchu.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-8-16", "subject": "fyzika", "stage": "2", "grade": "8", "title": "Šíření zvuku, ozvěna a sluch", "time": "10–20 min", "tag": "8. ročník · téma 16", "explain": "Ve vzduchu při přibližně 20 °C se zvuk šíří rychlostí asi 343 m/s. Ozvěna vzniká odrazem; dráha zvuku zahrnuje cestu tam i zpět. Hlasitý zvuk může poškodit sluch, proto pokusy provádíme potichu.", "paragraphs": ["Ve vzduchu při přibližně 20 °C se zvuk šíří rychlostí asi 343 m/s. Ozvěna vzniká odrazem; dráha zvuku zahrnuje cestu tam i zpět. Hlasitý zvuk může poškodit sluch, proto pokusy provádíme potichu.", "Ozvěna se vrátí za 1 s: odrazná stěna je přibližně 343 / 2 = 171,5 m daleko."], "diagram": "/schemata/fyzika-8-16.svg", "caption": "Graf kmitání v čase. Vzduchem se zvuk šíří jako podélné vlnění; tato křivka neukazuje tvar vzduchu.", "videos": [], "sources": [{"title": "8. ročník · doplněný výukový přehled", "url": null}, {"title": "RVP · energie", "url": "https://prohlednout.rvp.cz/ovu/cap-fyz-002-zv9-006"}]}, {"id": "fyzika-9-01", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Světlo a jeho šíření", "time": "10–20 min", "tag": "9. ročník · téma 1", "explain": "Světlo je elektromagnetické záření, které vnímáme zrakem. Ve stejnorodém průhledném prostředí se šíří přímočaře.", "paragraphs": ["Světlo je elektromagnetické záření, které vnímáme zrakem. Ve stejnorodém průhledném prostředí se šíří přímočaře.", "Zdroj světla: Těleso, které světlo vyzařuje, například Slunce, plamen nebo LED.", "Rychlost ve vakuu: Přibližně 300 000 km/s.", "Stín: Vzniká za neprůhlednou překážkou v důsledku přímočarého šíření světla."], "diagram": "/schemata/fyzika-9-01.svg", "caption": "Odraz světla: úhel dopadu se rovná úhlu odrazu. Oba úhly měříme od kolmice.", "videos": [{"id": "jp7nz-JMInM", "title": "Co je to světlo? · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-02", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Stín, polostín a zatmění", "time": "10–20 min", "tag": "9. ročník · téma 2", "explain": "Při osvětlení neprůhledného tělesa vzniká oblast stínu. Má-li zdroj světla větší rozměry, může vedle úplného stínu vzniknout také polostín.", "paragraphs": ["Při osvětlení neprůhledného tělesa vzniká oblast stínu. Má-li zdroj světla větší rozměry, může vedle úplného stínu vzniknout také polostín.", "Stín: Místo, do kterého nedopadá světlo z žádné části zdroje.", "Polostín: Místo osvětlené pouze částí zdroje.", "Zatmění Slunce: Měsíc se nachází mezi Sluncem a Zemí a jeho stín dopadá na Zemi.", "Zatmění Měsíce: Měsíc vstoupí do stínu Země.", "Pokus nebo pozorování: Pomocí lampy a dvou různě velkých míčků vytvořte model zatmění Slunce a Měsíce."], "diagram": "/schemata/fyzika-9-02.svg", "caption": "Odraz světla: úhel dopadu se rovná úhlu odrazu. Oba úhly měříme od kolmice.", "videos": [{"id": "jp7nz-JMInM", "title": "Co je to světlo? · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-03", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Odraz a lom světla", "time": "10–20 min", "tag": "9. ročník · téma 3", "explain": "Na rozhraní prostředí se část světla odráží a část může přecházet do druhého prostředí a lámat se.", "paragraphs": ["Na rozhraní prostředí se část světla odráží a část může přecházet do druhého prostředí a lámat se.", "Zákon odrazu: Úhel odrazu se rovná úhlu dopadu. Oba úhly měříme od kolmice.", "Lom světla: Při změně rychlosti světla na rozhraní se mění směr paprsku.", "Opticky hustší prostředí: Při vstupu do něj se paprsek obvykle láme ke kolmici.", "Pokus nebo pozorování: Pozorujte brčko ve sklenici s vodou a popište zdánlivou změnu jeho směru."], "diagram": "/schemata/fyzika-9-03.svg", "caption": "Odraz světla: úhel dopadu se rovná úhlu odrazu. Oba úhly měříme od kolmice.", "videos": [{"id": "jp7nz-JMInM", "title": "Co je to světlo? · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-04", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Zrcadla", "time": "10–20 min", "tag": "9. ročník · téma 4", "explain": "Zrcadlo vytváří obraz odrazem světla.", "paragraphs": ["Zrcadlo vytváří obraz odrazem světla.", "Rovinné zrcadlo: Obraz je zdánlivý, vzpřímený, stejně velký a stranově převrácený.", "Duté zrcadlo: Může vytvářet skutečný i zdánlivý obraz; soustřeďuje rovnoběžné paprsky.", "Vypuklé zrcadlo: Vytváří zmenšený zdánlivý obraz a poskytuje široké zorné pole.", "Paprsky významných směrů: Paprsek rovnoběžný s optickou osou se po odrazu od dutého zrcadla šíří ohniskem; paprsek vedený středem křivosti se vrací po stejné dráze."], "diagram": "/schemata/fyzika-9-04.svg", "caption": "Odraz světla: úhel dopadu se rovná úhlu odrazu. Oba úhly měříme od kolmice.", "videos": [{"id": "jp7nz-JMInM", "title": "Co je to světlo? · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-05", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Periskop", "time": "10–20 min", "tag": "9. ročník · téma 5", "explain": "Periskop umožňuje pozorovat přes překážku. Jednoduchý periskop využívá dvě rovnoběžná rovinná zrcadla skloněná přibližně pod úhlem 45°.", "paragraphs": ["Periskop umožňuje pozorovat přes překážku. Jednoduchý periskop využívá dvě rovnoběžná rovinná zrcadla skloněná přibližně pod úhlem 45°.", "Princip: Světlo se postupně odrazí od horního a dolního zrcadla do oka pozorovatele.", "Využití: Pozorování z krytu, historicky ponorky; moderní přístroje mohou používat hranoly a elektronické snímače.", "Zákon: Na obou zrcadlech platí zákon odrazu.", "Pokus nebo pozorování: Z kartonu a dvou malých zrcátek sestavte jednoduchý periskop. Dbejte na bezpečné upevnění hran zrcátek."], "diagram": "/schemata/fyzika-9-05.svg", "caption": "Odraz světla: úhel dopadu se rovná úhlu odrazu. Oba úhly měříme od kolmice.", "videos": [{"id": "jp7nz-JMInM", "title": "Co je to světlo? · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-06", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Čočky, lupa a mikroskop", "time": "10–20 min", "tag": "9. ročník · téma 6", "explain": "Čočka mění směr světelných paprsků lomem.", "paragraphs": ["Čočka mění směr světelných paprsků lomem.", "Spojka: Uprostřed je silnější a rovnoběžné paprsky soustřeďuje do ohniska.", "Rozptylka: Uprostřed je tenčí a paprsky rozptyluje.", "Lupa: Spojka používaná k pozorování zvětšeného zdánlivého obrazu.", "Mikroskop: Využívá soustavu čoček – objektiv a okulár.", "Ohnisková vzdálenost: f — metr m.", "Optická mohutnost: φ = 1/f — dioptrie D."], "diagram": "/schemata/fyzika-9-06.svg", "caption": "Spojka soustředí paprsky rovnoběžné s optickou osou do ohniska. Schéma znázorňuje ideální tenkou čočku.", "videos": [{"id": "jp7nz-JMInM", "title": "Co je to světlo? · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-07", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Zobrazení spojkou a rozptylkou", "time": "10–20 min", "tag": "9. ročník · téma 7", "explain": "Vlastnosti obrazu závisí na druhu čočky a na vzdálenosti předmětu od čočky.", "paragraphs": ["Vlastnosti obrazu závisí na druhu čočky a na vzdálenosti předmětu od čočky.", "Spojka: Může vytvořit skutečný převrácený obraz zachytitelný na stínítku, nebo zvětšený zdánlivý obraz při použití jako lupa.", "Rozptylka: Vytváří zdánlivý, vzpřímený a zmenšený obraz.", "Významné paprsky: Paprsek rovnoběžný s osou se u spojky láme do ohniska; paprsek procházející optickým středem se přibližně neláme.", "Bezpečnost: Spojkou nikdy nesoustřeďujeme přímé sluneční světlo do oka nebo na hořlavý materiál.", "Pokus nebo pozorování: Promítněte spojkou obraz vzdáleného předmětu na bílé stínítko a přibližně určete ohniskovou vzdálenost."], "diagram": "/schemata/fyzika-9-07.svg", "caption": "Spojka soustředí paprsky rovnoběžné s optickou osou do ohniska. Schéma znázorňuje ideální tenkou čočku.", "videos": [{"id": "jp7nz-JMInM", "title": "Co je to světlo? · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-08", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Lidské oko a vady zraku", "time": "10–20 min", "tag": "9. ročník · téma 8", "explain": "Oční čočka vytváří na sítnici skutečný, zmenšený a převrácený obraz. Mozek zrakový vjem zpracuje.", "paragraphs": ["Oční čočka vytváří na sítnici skutečný, zmenšený a převrácený obraz. Mozek zrakový vjem zpracuje.", "Akomodace: Změna tvaru čočky při zaostřování.", "Krátkozrakost: Obraz vzniká před sítnicí; koriguje se rozptylkou.", "Dalekozrakost: Obraz by vznikal za sítnicí; koriguje se spojkou.", "Ochrana zraku: Nikdy se nedíváme přímo do Slunce ani do laserového paprsku."], "diagram": "/schemata/fyzika-9-08.svg", "caption": "Spojka soustředí paprsky rovnoběžné s optickou osou do ohniska. Schéma znázorňuje ideální tenkou čočku.", "videos": [{"id": "jp7nz-JMInM", "title": "Co je to světlo? · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-09", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Sluneční soustava", "time": "10–20 min", "tag": "9. ročník · téma 9", "explain": "Sluneční soustavu tvoří Slunce a tělesa, která jsou k němu gravitačně vázána.", "paragraphs": ["Sluneční soustavu tvoří Slunce a tělesa, která jsou k němu gravitačně vázána.", "Planety: Merkur, Venuše, Země, Mars, Jupiter, Saturn, Uran a Neptun.", "Další tělesa: Trpasličí planety, planetky, komety, meteoroidy a přirozené družice.", "Slunce: Hvězda a hlavní zdroj energie pro Zemi."], "diagram": "/schemata/fyzika-9-09.svg", "caption": "Země obíhá Slunce a Měsíc obíhá Zemi. Schéma nezobrazuje skutečný poměr vzdáleností a velikostí.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}]}, {"id": "fyzika-9-10", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Pohyby Země a Měsíce", "time": "10–20 min", "tag": "9. ročník · téma 10", "explain": "Otáčení Země kolem osy způsobuje střídání dne a noci. Oběh Země kolem Slunce spolu se sklonem zemské osy způsobuje roční období.", "paragraphs": ["Otáčení Země kolem osy způsobuje střídání dne a noci. Oběh Země kolem Slunce spolu se sklonem zemské osy způsobuje roční období.", "Den: Jedna otočka Země trvá přibližně 24 hodin.", "Rok: Jeden oběh Země kolem Slunce trvá přibližně 365,25 dne.", "Měsíční fáze: Vznikají změnou vzájemné polohy Slunce, Země a Měsíce.", "Zatmění: Nastává při přibližném seřazení těchto těles."], "diagram": "/schemata/fyzika-9-10.svg", "caption": "Síla může změnit pohyb tělesa. Pro práci W = F · s musí být stálá síla rovnoběžná s posunutím.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}]}, {"id": "fyzika-9-11", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Orientace na obloze", "time": "10–20 min", "tag": "9. ročník · téma 11", "explain": "Poloha těles na obloze se popisuje vzhledem k obzoru a světovým stranám.", "paragraphs": ["Poloha těles na obloze se popisuje vzhledem k obzoru a světovým stranám.", "Polárka: Leží blízko severního nebeského pólu a pomáhá určit sever.", "Souhvězdí: Oblasti oblohy s tradičními obrazci hvězd.", "Pozorování: Mění se během noci i roku vlivem pohybů Země.", "Pokus nebo pozorování: Najděte na mapě oblohy Velký vůz a pomocí jeho zadních hvězd určete směr k Polárce."], "diagram": "/schemata/fyzika-9-11.svg", "caption": "Země obíhá Slunce a Měsíc obíhá Zemi. Schéma nezobrazuje skutečný poměr vzdáleností a velikostí.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}]}, {"id": "fyzika-9-12", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Magnetické pole elektrického proudu", "time": "10–20 min", "tag": "9. ročník · téma 12", "explain": "Kolem vodiče, kterým prochází elektrický proud, vzniká magnetické pole.", "paragraphs": ["Kolem vodiče, kterým prochází elektrický proud, vzniká magnetické pole.", "Ørstedovo pozorování: Kompas v blízkosti vodiče s proudem se vychýlí.", "Směr pole: Závisí na směru elektrického proudu.", "Cívka: Pole cívky se podobá poli tyčového magnetu.", "Pokus nebo pozorování: Ve skupině přibližte kompas k vodiči napájenému bezpečným nízkým napětím. Krátce uzavřete obvod a sledujte výchylku střelky."], "diagram": "/schemata/fyzika-9-12.svg", "caption": "Magnetické pole tyčového magnetu. Vnější směr siločar je od severního k jižnímu pólu.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-13", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Elektromagnet", "time": "10–20 min", "tag": "9. ročník · téma 13", "explain": "Elektromagnet tvoří cívka s elektrickým proudem, často s jádrem z magneticky měkké oceli.", "paragraphs": ["Elektromagnet tvoří cívka s elektrickým proudem, často s jádrem z magneticky měkké oceli.", "Zesílení účinku: Více závitů, větší proud a vhodné feromagnetické jádro.", "Výhoda: Magnetický účinek lze zapínat, vypínat a měnit.", "Využití: Relé, elektrický zvonek, jeřáb na kovový odpad a elektromagnetické zámky."], "diagram": "/schemata/fyzika-9-13.svg", "caption": "Magnetické pole tyčového magnetu. Vnější směr siločar je od severního k jižnímu pólu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}]}, {"id": "fyzika-9-14", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Elektromotor", "time": "10–20 min", "tag": "9. ročník · téma 14", "explain": "Elektromotor mění elektrickou energii na mechanickou práci.", "paragraphs": ["Elektromotor mění elektrickou energii na mechanickou práci.", "Princip: Na vodič s proudem v magnetickém poli působí síla.", "Otáčivý účinek: Síly působící na cívku vytvoří moment, který ji roztáčí.", "Využití: Ventilátory, čerpadla, stroje, domácí spotřebiče a dopravní prostředky.", "Pokus nebo pozorování: Sestavte jednoduchý stejnosměrný motorek nebo homopolární motor pouze podle bezpečného návodu učitele."], "diagram": "/schemata/fyzika-9-14.svg", "caption": "Magnetické pole tyčového magnetu. Vnější směr siločar je od severního k jižnímu pólu.", "videos": [{"id": "r7vzux7l9y8", "title": "Jak funguje elektromotor · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-15", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Elektromagnetická indukce", "time": "10–20 min", "tag": "9. ročník · téma 15", "explain": "Při změně magnetického pole v okolí vodiče nebo cívky vzniká indukované napětí a v uzavřeném obvodu proud.", "paragraphs": ["Při změně magnetického pole v okolí vodiče nebo cívky vzniká indukované napětí a v uzavřeném obvodu proud.", "Podmínka: Rozhodující je změna magnetického toku, nikoli samotná přítomnost magnetu.", "Zvětšení účinku: Rychlejší změna pole, více závitů nebo silnější magnet.", "Využití: Generátor, dynamo, transformátor, indukční nabíjení.", "Pokus nebo pozorování: Pohybujte magnetem dovnitř a ven z cívky připojené k citlivému měřidlu. Porovnejte směr výchylky."], "diagram": "/schemata/fyzika-9-15.svg", "caption": "Magnetické pole tyčového magnetu. Vnější směr siločar je od severního k jižnímu pólu.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}]}, {"id": "fyzika-9-16", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Střídavý proud", "time": "10–20 min", "tag": "9. ročník · téma 16", "explain": "U střídavého proudu se směr a velikost proudu periodicky mění. V elektrické síti v ČR je frekvence 50 Hz.", "paragraphs": ["U střídavého proudu se směr a velikost proudu periodicky mění. V elektrické síti v ČR je frekvence 50 Hz.", "Stejnosměrný proud: Má stálý směr; zdrojem může být článek nebo akumulátor.", "Střídavý proud: Směr se pravidelně mění; vzniká v alternátorech elektráren.", "Efektivní napětí sítě: Přibližně 230 V; je životu nebezpečné.", "Perioda: T — sekunda s.", "Frekvence: f = 1/T — hertz Hz.", "Síťová frekvence: f — 50 Hz."], "diagram": "/schemata/fyzika-9-16.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-17", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Měření střídavého proudu a napětí", "time": "10–20 min", "tag": "9. ročník · téma 17", "explain": "Pro měření volíme správný přístroj, rozsah a režim AC. Ampérmetr zapojujeme sériově, voltmetr paralelně.", "paragraphs": ["Pro měření volíme správný přístroj, rozsah a režim AC. Ampérmetr zapojujeme sériově, voltmetr paralelně.", "Bezpečnost: Ve škole pracujeme pouze s bezpečným nízkým napětím a podle pokynů učitele.", "Multimetr: Před připojením ověříme zdířky, rozsah a typ měřené veličiny.", "Nikdy: Neměříme proud přímým připojením ampérmetru ke zdroji napětí."], "diagram": "/schemata/fyzika-9-17.svg", "caption": "Příklad stupnice: odečet vyžaduje znalost jednotky, rozsahu a hodnoty nejmenšího dílku.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-18", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Transformátor", "time": "10–20 min", "tag": "9. ročník · téma 18", "explain": "Transformátor mění velikost střídavého napětí pomocí elektromagnetické indukce.", "paragraphs": ["Transformátor mění velikost střídavého napětí pomocí elektromagnetické indukce.", "Primární cívka: Je připojena ke zdroji střídavého napětí.", "Sekundární cívka: Indukuje se v ní střídavé napětí.", "Převod: Poměr napětí přibližně odpovídá poměru počtu závitů.", "Napětí a závity: U₂/U₁ = N₂/N₁ — ideální transformátor.", "Výkon: P₁ ≈ P₂ — ztráty zanedbány.", "Příklad: Má-li sekundární cívka poloviční počet závitů, je sekundární napětí přibližně poloviční."], "diagram": "/schemata/fyzika-9-18.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-19", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Rozvodná elektrická síť", "time": "10–20 min", "tag": "9. ročník · téma 19", "explain": "Elektrická energie se přenáší na velké vzdálenosti při vysokém napětí, aby byly ztráty ve vedení menší.", "paragraphs": ["Elektrická energie se přenáší na velké vzdálenosti při vysokém napětí, aby byly ztráty ve vedení menší.", "Elektrárna: Generátor vyrábí střídavé napětí.", "Transformace: Napětí se pro přenos zvýší a před spotřebitelem postupně sníží.", "Domácnost: Zásuvkové napětí je přibližně 230 V; mezi fázemi třífázové sítě přibližně 400 V.", "Ochranné prvky: Jističe, pojistky, proudové chrániče a ochranný vodič."], "diagram": "/schemata/fyzika-9-19.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-20", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Vedení elektrického proudu v kapalinách a plynech", "time": "10–20 min", "tag": "9. ročník · téma 20", "explain": "V kapalinách vedou proud pohybující se ionty. V plynech proud prochází po ionizaci.", "paragraphs": ["V kapalinách vedou proud pohybující se ionty. V plynech proud prochází po ionizaci.", "Elektrolyt: Roztok nebo tavenina obsahující volně pohyblivé ionty.", "Elektrolýza: Chemické změny vyvolané průchodem proudu elektrolytem.", "Výboj v plynu: Jiskra, oblouk, doutnavý výboj nebo blesk.", "Nebezpečí: Výboje a proud ve vodivých roztocích mohou způsobit úraz, požár nebo poškození zařízení."], "diagram": "/schemata/fyzika-9-20.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}]}, {"id": "fyzika-9-21", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Elektrická bezpečnost a první pomoc", "time": "10–20 min", "tag": "9. ročník · téma 21", "explain": "Elektrický proud může způsobit popálení, svalové křeče, poruchu srdeční činnosti nebo zástavu dechu.", "paragraphs": ["Elektrický proud může způsobit popálení, svalové křeče, poruchu srdeční činnosti nebo zástavu dechu.", "První krok: Nedotýkáme se zasaženého, dokud není bezpečně přerušen přívod proudu.", "Pomoc: Vypneme zdroj, zavoláme 155 nebo 112 a postupujeme podle pokynů operátora.", "Resuscitace: Pokud postižený nedýchá normálně, zahájíme nepřímou masáž srdce a použijeme AED, je-li dostupný.", "Prevence: Suché ruce, nepoškozené kabely, správné jištění a zákaz manipulace se síťovým napětím bez oprávnění.", "K vysokému napětí a spadlým elektrickým vodičům se nepřibližuj. Přivolej dospělého a záchrannou službu; nikdy se nepokoušej člověka oddělit od vodiče. Po úrazu elektrickým proudem je nutné lékařské vyšetření."], "diagram": "/schemata/fyzika-9-21.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [{"id": "go58LnpIlV0", "title": "Elektřina · AV ČR"}], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}, {"title": "Akademie věd ČR · výuková videa", "url": "https://www.avcr.cz/cs/pro-verejnost/vyukova-videa/"}, {"title": "Český červený kříž · první pomoc", "url": "https://www.cervenykriz.eu/prvni-pomoc"}]}, {"id": "fyzika-9-22", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Polovodiče typu N a P", "time": "10–20 min", "tag": "9. ročník · téma 22", "explain": "Polovodiče mají elektrickou vodivost mezi vodiči a izolanty. Jejich vodivost lze výrazně ovlivnit teplotou, světlem a příměsemi.", "paragraphs": ["Polovodiče mají elektrickou vodivost mezi vodiči a izolanty. Jejich vodivost lze výrazně ovlivnit teplotou, světlem a příměsemi.", "Polovodič typu N: Většinovými nosiči náboje jsou elektrony.", "Polovodič typu P: Většinovými nosiči jsou díry.", "Přechod PN: Rozhraní oblastí P a N; jeho chování závisí na polaritě připojeného napětí.", "Příklady: Křemík, germanium; součástky LED, termistory, fotodiody a tranzistory."], "diagram": "/schemata/fyzika-9-22.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}]}, {"id": "fyzika-9-23", "subject": "fyzika", "stage": "2", "grade": "9", "title": "Polovodičová dioda a usměrňovač", "time": "10–20 min", "tag": "9. ročník · téma 23", "explain": "Dioda propouští proud převážně jedním směrem.", "paragraphs": ["Dioda propouští proud převážně jedním směrem.", "Propustný směr: Anoda je na vyšším potenciálu než katoda; dioda může vést.", "Závěrný směr: Dioda běžně proud téměř nepropouští.", "Usměrnění: Dioda převádí střídavý průběh na jednosměrný pulzující proud.", "LED: Svítivá dioda musí být zapojena se správnou polaritou a s omezovacím rezistorem.", "Pokus nebo pozorování: Zapojte LED s ochranným rezistorem ke školnímu nízkonapěťovému zdroji a ověřte, že svítí jen při správné polaritě."], "diagram": "/schemata/fyzika-9-23.svg", "caption": "Jednoduchý uzavřený bateriový obvod. U elektrických strojů slouží jako připomenutí zdroje a spotřebiče.", "videos": [], "sources": [{"title": "Podklad: Jakub Rund · Fyzika 9. ročníku", "url": null}]}]);